export const DEFAULT_JURISDICTION: JurisdictionRates = {
  state: "—", stateName: "Other / Not Configured", ratesAsOf: "1970-01-01",
  titleInsuranceRate: 0.005, titleInsuranceParty: "split",
  transferTaxes: [
    { name: "Transfer Tax (placeholder)", rate: 0.005, rateMin: 0, rateMax: 0.02, base: "price", party: "seller", verify: true,
      source: "National-average placeholder — state not configured", asOf: "1970-01-01",
      notes: "This state isn't configured. Verify actual rates and splits via the Fidelity guide or a local title officer." },
  ],
  localLevel: "none",
  localLevelSource: { source: "Not configured", asOf: "1970-01-01", statement: "State not configured — nothing here is verified." },
  recordingFeesFlat: 100,
  notes: "This state is not configured with sourced data. Figures are placeholders — do not rely on them.",
};

/** State-level data only (local table NOT loaded — the engine treats locality as unverified until it is). */
export function getJurisdiction(stateAbbr?: string | null): JurisdictionRates {
  if (!stateAbbr) return DEFAULT_JURISDICTION;
  return CLOSING_COSTS_BY_STATE[stateAbbr.toUpperCase().trim()] ?? DEFAULT_JURISDICTION;
}

/** State data WITH its local table loaded (async — the big tables are lazy chunks). */
export async function getJurisdictionFull(stateAbbr?: string | null): Promise<JurisdictionRates> {
  const j = getJurisdiction(stateAbbr);
  if (!hasLocalTable(j.state)) return j;
  const local = await loadLocalTable(j.state);
  return local ? { ...j, local } : j;
}

/**
 * Deed transfer taxes as % of price, by party — price-based tax lines only (no title,
 * no recording fees, no loan-based taxes). Unverified local layers count at their LOW
 * end; check `breakdown.local.status` before trusting it.
 */
export function transferTaxPct(b: ClosingCostBreakdown): { seller: number; buyer: number } {
  if (!b.price) return { seller: 0, buyer: 0 };
  let seller = 0, buyer = 0;
  for (const l of b.lines) {
    if (l.inactive || l.base !== "price" || (l.scope !== "state" && l.scope !== "local")) continue;
    seller += l.seller + (l.range?.sellerMin ?? 0);
    buyer += l.buyer + (l.range?.buyerMin ?? 0);
  }
  return { seller: (seller / b.price) * 100, buyer: (buyer / b.price) * 100 };
}
